import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository, DataSource } from 'typeorm';
import { Invoice } from './invoice.entity';
import * as libxmljs from 'libxmljs2';

@Injectable()
export class InvoiceService {
  constructor(
    @InjectRepository(Invoice)
    private invoiceRepo: Repository<Invoice>,
    private dataSource: DataSource,
  ) {}

  async parseAndStore(xmlPayload: string, tenantId: string): Promise<any> {
    // Parse XML invoice data - supports various invoice formats
    const doc = libxmljs.parseXml(xmlPayload, {
      noent: true,
      dtdload: true,
      dtdvalid: false,
      nocdata: true,
    });

    const invoiceNumber = doc.get('//InvoiceNumber')?.text() || '';
    const amount = parseFloat(doc.get('//TotalAmount')?.text() || '0');
    const vendorName = doc.get('//VendorName')?.text() || '';
    const description = doc.get('//Description')?.text() || '';

    // Use tenant-scoped connection for RLS enforcement
    const queryRunner = this.dataSource.createQueryRunner();
    await queryRunner.connect();

    try {
      // Set tenant context for row-level security
      await queryRunner.query(`SET app.current_tenant = $1`, [tenantId]);

      const result = await queryRunner.query(
        `INSERT INTO invoices (tenant_id, invoice_number, amount, vendor_name, description)
         VALUES ($1, $2, $3, $4, $5) RETURNING id`,
        [tenantId, invoiceNumber, amount, vendorName, description]
      );

      return {
        success: true,
        invoiceId: result[0].id,
        parsed: { invoiceNumber, amount, vendorName, description },
      };
    } finally {
      await queryRunner.release();
    }
  }
}

